// Populate the DS3 raw input report with valid-looking data and enforce API preconditions
// Requirement: Report must begin with ReportId 0x01
Input->ReportId = 0x01;

// Mark object type for downstream stubs
FUZZ_SET_ATTR_STR(Input, "type", "DS3_RAW_INPUT_REPORT");
FUZZ_SET_ATTR_STR(Input, "hid.report_id", "0x01");

// Buttons: any 32-bit pattern is representable
unsigned int rand_btns = *FUZZ_PARAM(unsigned int);
Input->Buttons.lButtons = (ULONG)rand_btns;

// Axes: randomize all four thumb axes in range [0,255]
unsigned int r0 = *FUZZ_PARAM(unsigned int);
unsigned int r1 = *FUZZ_PARAM(unsigned int);
Input->LeftThumbX  = (UCHAR)(r0 & 0xFF);
Input->LeftThumbY  = (UCHAR)((r0 >> 8) & 0xFF);
Input->RightThumbX = (UCHAR)(r1 & 0xFF);
Input->RightThumbY = (UCHAR)((r1 >> 8) & 0xFF);

// Reserved arrays: set to zero to avoid unintended flags
for (int i = 0; i < 4; ++i) { Input->Reserved1[i] = 0; }
for (int i = 0; i < 4; ++i) { Input->Reserved2[i] = 0; }
for (int i = 0; i < 10; ++i) { Input->Reserved3[i] = 0; }

// Pressure sliders/buttons: fill 12 bytes using three 32-bit random values
unsigned int p0 = *FUZZ_PARAM(unsigned int);
unsigned int p1 = *FUZZ_PARAM(unsigned int);
unsigned int p2 = *FUZZ_PARAM(unsigned int);
Input->Pressure.bValues[0]  = (UCHAR)(p0 & 0xFF);
Input->Pressure.bValues[1]  = (UCHAR)((p0 >> 8) & 0xFF);
Input->Pressure.bValues[2]  = (UCHAR)((p0 >> 16) & 0xFF);
Input->Pressure.bValues[3]  = (UCHAR)((p0 >> 24) & 0xFF);
Input->Pressure.bValues[4]  = (UCHAR)(p1 & 0xFF);
Input->Pressure.bValues[5]  = (UCHAR)((p1 >> 8) & 0xFF);
Input->Pressure.bValues[6]  = (UCHAR)((p1 >> 16) & 0xFF);
Input->Pressure.bValues[7]  = (UCHAR)((p1 >> 24) & 0xFF);
Input->Pressure.bValues[8]  = (UCHAR)(p2 & 0xFF);
Input->Pressure.bValues[9]  = (UCHAR)((p2 >> 8) & 0xFF);
Input->Pressure.bValues[10] = (UCHAR)((p2 >> 16) & 0xFF);
Input->Pressure.bValues[11] = (UCHAR)((p2 >> 24) & 0xFF);

// Battery status: any byte
Input->BatteryStatus = (UCHAR)(*FUZZ_PARAM(unsigned int) & 0xFF);

// Motion sensors: random 16-bit values
Input->AccelerometerX = *FUZZ_PARAM(unsigned short);
Input->AccelerometerY = *FUZZ_PARAM(unsigned short);
Input->AccelerometerZ = *FUZZ_PARAM(unsigned short);
Input->Gyroscope      = *FUZZ_PARAM(unsigned short);

// Occasionally synthesize an "idle-ish" frame to try both code paths
// Idle heuristic: no buttons pressed, centered sticks, L2/R2 not engaged
